def binary_search(xs, target):
    lo, hi = 0, len(xs) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if xs[mid] == target:
            return mid
        if xs[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

from decimal import Decimal, ROUND_HALF_UP

def apply_vat(net, rate):
    gross = Decimal(str(net)) * (Decimal('1') + Decimal(str(rate)))
    return float(gross.quantize(Decimal('0.01'), rounding=ROUND_HALF_UP))
